/// <summary>
///code added by TCS for multi select lookup  
/// </summary>
[ExtensionOf(formstr(LedgerJournalSetup))]
final class MET_LedgerJournalSetup_Extension
{
    public SysLookupMultiSelectCtrl    msCtrl;
    
}

Method.Source:
    public Query builPaymModeQuery()
    {
        Query   vendPaymQry = new Query(querystr(MET_VendPaymModeTableQry));
        //vendPaymQry.dataSourceTable(tableNum(VendPaymModeTable));

        return vendPaymQry;
    }

container getSelectedNotes(str _noteStr)
{
    VendPaymModeTable   vendPaymModeTable;
    container   tmpValues, conIds, conName;
    int         idx;
 
    if(_noteStr)
    {
        tmpValues = str2con(_noteStr, ';');
    }
 
    for(idx=1; idx<=conLen(tmpValues); idx++)
    {
        vendPaymModeTable = vendPaymModeTable::find(conPeek(tmpValues, idx));
        conIds += vendPaymModeTable.RecId;
        conName += vendPaymModeTable.PaymMode;
    }
 
    return [conIds, conName, conIds];
}

    /// <summary>
    /// Code for the multi-lookup on form init
    /// </summary>
    /// formrun
    /// event args
    [FormEventHandler(formStr(LedgerJournalSetup), FormEventType::Initialized)]
    public void LedgerJournalSetup_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        vendPaymModeTable   vendPaymModeTable;
        Query               payModeTypeQry   =   this.builPaymModeQuery();
        FormStringControl   DocuTypes        =   this.design().controlName('LedgerJournalName_MET_PaymMode');
        //InventParameters    inventParameters    =   InventParameters::find();
 
        msCtrl   = SysLookupMultiSelectCtrl::construct(this,
                                            DocuTypes,
                                            queryStr(MET_VendPaymModeTableQry),
                                            false,
            [tableNum(vendPaymModeTable), fieldNum(vendPaymModeTable,PaymMode)]);
        
        select vendPaymModeTable where vendPaymModeTable.DataAreaId == curExt();

        msCtrl.refreshQuery(payModeTypeQry);
        msCtrl.set(this.getSelectedNotes(vendPaymModeTable.PaymMode));
    }

   /// <summary>
   ///
   /// </summary>
   /// <param name="sender"></param>
   /// <param name="e"></param>
   [FormControlEventHandler(formControlStr(LedgerJournalSetup, LedgerJournalName_MET_PaymMode), FormControlEventType::Modified)]
   public void LedgerJournalName_MET_PaymMode_OnModified(FormControl sender, FormControlEventArgs e)
   {
       FormRun     formRun = sender.formRun();

       LedgerJournalName    ledgerJourName    =   formRun.dataSource(FormDataSourceStr(LedgerJournalSetup, LedgerJournalName)).cursor();
       ledgerJourName.MET_PaymMode = con2Str(msCtrl.getSelectedFieldValues(), ';');
   }
